<?php ui_header($data['title'],$data['company']['name'].' · '.$data['level'].' · '.$data['jobType'].' · '.($data['location']??'Remote'));$savedIds=$user?$app->api('users/me/saved-jobs/ids'):[];$already=null;if($user&&$user['role']==='CANDIDATE')foreach($app->api('applications/me') as $a)if($a['jobId']===$data['id'])$already=$a; ?>
<div class="grid detail section"><article class="panel"><h2>Mô tả công việc</h2><div class="prose"><?= nl2br(e(strip_tags($data['description']))) ?></div><?php if(!empty($data['requirements'])): ?><h2 class="section">Yêu cầu ứng viên</h2><p class="prose"><?= nl2br(e($data['requirements'])) ?></p><?php endif; ?><h2 class="section">Mức lương</h2><p class="job-salary"><?= e(ui_salary($data)) ?></p><h2 class="section">Kỹ năng yêu cầu</h2><div class="chips"><?php foreach($data['requiredSkills'] as $skill): ?><span class="skill-match"><?= e($skill) ?></span><?php endforeach; ?></div><?php if(!empty($data['benefits'])): ?><h2 class="section">Quyền lợi</h2><p class="prose"><?= nl2br(e(is_array($data['benefits'])?implode("\n",$data['benefits']):$data['benefits'])) ?></p><?php endif; ?><p class="section"><a href="/company/<?= e($data['companyId']) ?>">Tìm hiểu công ty →</a></p></article><aside><section class="panel"><h2>Ứng tuyển ngay</h2><?php if($user&&$user['role']==='CANDIDATE'): if($already): ?><p>Bạn đã ứng tuyển vị trí này.</p><a class="button" href="/applications/<?= e($already['id']) ?>">Xem đơn ứng tuyển</a><?php else: ?><form data-api="/applications" data-redirect="/applications"><input type="hidden" name="jobId" value="<?= e($data['id']) ?>"><label>Chọn CV<select name="cvFileId" required><?php foreach($cvs as $cv): ?><option value="<?= e($cv['id']) ?>" <?= $cv['isPrimary']?'selected':'' ?>><?= e($cv['fileName']) ?></option><?php endforeach; ?></select></label><label>Tải lên CV mới<input type="file" data-screen-upload accept=".pdf,.docx"></label><label>Thư giới thiệu<textarea name="coverLetter" placeholder="Giới thiệu ngắn về kinh nghiệm và lý do bạn phù hợp với vị trí này..."></textarea></label><p class="form-error" role="alert" hidden></p><button type="submit">Nộp hồ sơ</button></form><?php endif; ?><div class="section"><button class="ghost" data-job-save="<?= e($data['id']) ?>" data-external="false" aria-pressed="<?= in_array($data['id'],$savedIds,true)?'true':'false' ?>" aria-label="Lưu việc làm"><?= ui_icon('bookmark',16) ?> Lưu việc làm</button></div><?php elseif(!$user): ?><p class="muted">Đăng nhập để chọn CV và ứng tuyển.</p><a class="button" href="/auth/sign-in">Đăng nhập</a><?php else: ?><p class="muted">Chỉ tài khoản ứng viên mới có thể nộp hồ sơ.</p><?php endif; ?></section><section class="panel section"><h2><?= e($data['company']['name']) ?></h2><p class="muted"><?= e($data['location']??'Remote') ?></p><span class="status-badge"><?= e($data['status']) ?></span><p>Hạn tuyển: <?= !empty($data['expiresAt'])?e(date('d/m/Y',strtotime($data['expiresAt']))):'—' ?></p></section></aside></div>